def _strict_tenant(self, parts):
    """Single header or single query tenant, with conflict auditing.

    Same rules as _audit_tenant (simultaneous/duplicate/empty/missing
    is a 400 naming tenant_id), but the failure is also written to the
    ledger as an invisible tenant_conflict event. Used by the policy
    management endpoints.
    """
    headers = self.headers.get_all("X-Tenant-Id") or []
    query_values = parse_qs(
        parts.query, keep_blank_values=True
    ).get("tenant_id", [])

    def fail(message: str) -> None:
        if self._record_conflict():
            self._bad_request(message)

    if len(headers) > 1:
        fail("duplicate tenant_id (provide a single X-Tenant-Id header)")
        return None
    if len(query_values) > 1:
        fail("duplicate tenant_id (provide a single tenant_id parameter)")
        return None
    if headers and query_values:
        fail(
            "conflicting tenant_id parameters (use header or query, not both)"
        )
        return None
    tenant = headers[0] if headers else (
        query_values[0] if query_values else None
    )
    if tenant is None:
        fail("missing required field: tenant_id")
        return None
    if not tenant:
        fail("field tenant_id must be a non-empty string")
        return None
    return tenant

def do_PUT(self) -> None:
    parts = urlsplit(self.path)
    if parts.path != _POLICY_PATH:
        self._send_json(404, {"error": "not found"})
        return
    operator = self._operator()
    if operator is None:
        return
    try:
        self._put_policy(parts)
    except LedgerError as exc:
        self._server_error(exc)
    except PolicyStoreUnavailable:
        self._send_json(
            500, {"error": "policy store is unavailable"}
        )
    except PolicyRevisionConflict as exc:
        self._revision_conflict(exc)

def do_DELETE(self) -> None:
    parts = urlsplit(self.path)
    if parts.path != _POLICY_PATH:
        self._send_json(404, {"error": "not found"})
        return
    operator = self._operator()
    if operator is None:
        return
    try:
        self._delete_policy(parts)
    except LedgerError as exc:
        self._server_error(exc)
    except PolicyStoreUnavailable:
        self._send_json(
            500, {"error": "policy store is unavailable"}
        )
    except PolicyRevisionConflict as exc:
        self._revision_conflict(exc)

def _revision_conflict(self, exc: PolicyRevisionConflict) -> None:
    """Send the fixed 409 body for a failed optimistic precondition."""
    self._send_json(
        409,
        {
            "error": "policy revision conflict",
            "current_revision": exc.current_revision,
        },
    )

def _expected_revision(self, parts):
    """Parse the optional expected_revision query parameter.

    Returns None when omitted (unconditional), ``'none'`` or a
    revision string. A duplicated or empty parameter is a plain 400
    with zero side effects (no tenant_conflict, no rule change).
    """
    values = parse_qs(
        parts.query, keep_blank_values=True
    ).get("expected_revision", [])
    if len(values) > 1:
        self._bad_request(
            "duplicate expected_revision (provide a single "
            "expected_revision parameter)"
        )
        return _MISSING
    if not values:
        return None
    raw = values[0]
    if not raw:
        self._bad_request(
            "field expected_revision must be a revision or 'none'"
        )
        return _MISSING
    try:
        return validate_expected_revision(raw)
    except PolicyError as exc:
        self._bad_request(str(exc))
        return _MISSING

def _get_policy(self, parts) -> None:
    tenant_id = self._strict_tenant(parts)
    if tenant_id is None:
        return
    try:
        rules = policy_store.get_strict(tenant_id)
    except PolicyStoreUnavailable:
        self._send_json(
            500, {"error": "policy store is unavailable"}
        )
        return
    if rules is None:
        self._send_json(404, {"error": "policy not found"})
        return
    policy_store.audit_read(tenant_id)
    self._send_json(
        200,
        {
            "tenant_id": tenant_id,
            "rules": [r.to_json() for r in rules],
            "revision": revision_for_rules(rules),
        },
    )

def _check_policy(self, parts) -> None:
    """POST /v1/policy/check: evaluate one subject/action, read-only.

    Tenant and operator follow the GET policy rules (a source
    conflict is the usual audited tenant_conflict). The body carries
    ``subject`` and ``action`` and optionally ``key_id``; every
    body/parameter failure is a 400 naming the field with no audit
    event. ``key_id`` must be null or a canonical UUID4: omitted,
    the response keeps its legacy shape and the decision matches
    only unscoped rules; present (including null), the response

            includes it and scoped rules for it participate. A successful
            check writes nothing: no audit event, no revision, no file
            change.
            """
            tenant_id = self._strict_tenant(parts)
            if tenant_id is None:
                return
            payload = self._read_json_object(audit=False)
            if payload is None:
                return
            unknown = set(payload) - {"subject", "action", "key_id"}
            if unknown:
                self._bad_request("unknown field: %s" % sorted(unknown)[0])
                return
            if "subject" not in payload:
                self._bad_request("missing required field: subject")
                return
            subject = payload["subject"]
            if not isinstance(subject, str) or not subject:
                self._bad_request(
                    "field subject must be a non-empty string"
                )
                return
            if "action" not in payload:
                self._bad_request("missing required field: action")
                return
            action = payload["action"]
            if not isinstance(action, str) or not action:
                self._bad_request(
                    "field action must be a non-empty string"
                )
                return
            if action not in POLICY_ACTIONS:
                self._bad_request(
                    "field action has unknown action %r (allowed: %s)"
                    % (action, ", ".join(POLICY_ACTIONS))
                )
                return
            # key_id is optional; when present it must be null or a
            # canonical UUID4 -- the fixed text is part of the contract.
            key_id = None
            if "key_id" in payload:
                raw_key_id = payload["key_id"]
                if raw_key_id is not None and not is_valid_key_id(raw_key_id):
                    self._bad_request(
                        "field key_id must be a UUID4 or null"
                    )
                    return
                key_id = raw_key_id
            try:
                result = policy_store.check(tenant_id, subject, action, key_id)
            except PolicyStoreUnavailable:
                self._send_json(
                    500, {"error": "policy store is unavailable"}
                )
                return
            response = {
                "tenant_id": tenant_id,
                "subject": subject,
                "action": action,
            }
            if "key_id" in payload:
                # Present requests (including explicit null) carry the
                # requested key_id directly after the action; omitted keeps
                # the legacy key order byte-for-byte.
                response["key_id"] = key_id
            response.update(
                {
                    "allowed": result["allowed"],
                    "effect": result["effect"],
                    "reason": result["reason"],
                    "rules": [rule.to_json() for rule in result["rules"]],
                }
            )
            self._send_json(200, response)

        def _put_policy(self, parts) -> None:
            payload = self._read_json_object()
            if payload is None:
                return
            body_tenant = payload.get("tenant_id")
            if not isinstance(body_tenant, str) or not body_tenant:
                if self._record_conflict():
                    self._bad_request(
                        "field tenant_id must be a non-empty string"
                    )
                return
            tenant_id = self._tenant(parts, payload)
            if tenant_id is None:
                return
            if "rules" not in payload:
                self._bad_request("missing required field: rules")
                return
            try:
                rules = validate_rules(payload["rules"])
            except PolicyError as exc:
                self._bad_request(str(exc))
                return
            expected = self._expected_revision(parts)
            if expected is _MISSING:
                return
            rules, new_revision = policy_store.put(
                tenant_id, rules, expected_revision=expected
            )
            self._send_json(
                200,
                {
                    "tenant_id": tenant_id,
                    "rules": [r.to_json() for r in rules],
                    "revision": new_revision,
                },
            )

        def _delete_policy(self, parts) -> None:
            tenant_id = self._strict_tenant(parts)
            if tenant_id is None:
                return
            expected = self._expected_revision(parts)
            if expected is _MISSING:
                return
            policy_store.delete(tenant_id, expected_revision=expected)
            self._send_json(200, {"tenant_id": tenant_id, "deleted": True})

    return KeyHandler


